const axios = require('axios');

// API Configuration
const API_KEY = 'YOUR_API_KEY';
const BASE_URL = 'https://api.transitfm.io/v1';

const headers = {
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${API_KEY}`
};

// Work Order Data
const workOrderData = {
  title: 'HVAC Filter Replacement - Building A',
  description: 'Replace main HVAC filter in Building A with MERV-13 rated filter. Check filter pressure drop gauge and document readings.',
  facility_id: 'fac-789',
  category: 'preventive',
  priority: 'medium',
  assigned_to_id: 'user-456',
  estimated_hours: 1.5,
  due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
  notes: 'Use MERV-13 filters. Building A main entrance lobby. Contact facility manager before starting work.'
};

// Create Work Order
axios.post(`${BASE_URL}/work-orders`, workOrderData, { headers })
  .then(response => {
    const createdWO = response.data;
    console.log(`Work Order Created: ${createdWO.id}`);
    console.log(`Status: ${createdWO.status}`);
    console.log(`Assigned To: ${createdWO.assigned_to.name}`);
  })
  .catch(error => {
    console.error(`Error: ${error.response.status}`);
    console.error(error.response.data);
  });
